/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimInventSiteId_Product extends UPSPricingAttributeInventDim_Product implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventSiteId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventSiteId from inventDim
        group by InventSiteId
    {
        ret.add(inventDim.InventSiteId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventSiteId));
    qbr.value(queryValue(_value));
}
